    CITATION_DOIS = [BBTOOLS_CITATION_DOI]
    CITATION_URLS = [f"{DOI_URL}{BBTOOLS_CITATION_DOI}"]
    CITATION_TEXT = BBTOOLS_CITATION_TEXT
    VERSION = "39.08"
